public abstract class GUPPricingRuleBuilder extends RunBase
{
    protected GUPPricingAttributeSourceLevel sourceLevel;
    protected FormRun callerForm;
    protected Common masterRecord;
    protected GUPPricingRule pricingRule;

    protected boolean dialogOk = true;

}

Method.Source:
public void new(GUPPricingAttributeSourceLevel _sourceLevel, FormRun _callerForm = null)
{
    super();

    this.sourceLevel = _sourceLevel;
    this.callerForm = _callerForm;
}

/// <summary>
/// This method init a master record which should later on link an <c>GUPPricingRule</c> record on it.
/// </summary>
public abstract void initMasterRecord()
{
}

/// <summary>
/// This method link created <c>GUPPricingRule</c> to master record.
/// </summary>
/// <param name = "_pricingRule">The <c>GUPPricingRule</c> to be linked.</param>
public abstract void linkPricingRule(GUPPricingRule _pricingRule)
{
}

/// <summary>
/// Create and return the master record linked with generated <c>GUPPricingRule</c>.
/// </summary>
/// <returns>The master record.</returns>
public final Common createRecord()
{
    this.run();

    return this.masterRecord;
}

public final void run()
{
    this.initMasterRecord();

    if (dialogOk)
    {
        ttsbegin;

        pricingRule.insert();
        this.linkPricingRule(pricingRule);

        if (dialogOk)
        {
            masterRecord.selectForUpdate(true);
            masterRecord.write();
        }
        else
        {
            pricingRule.delete();
        }

        ttscommit;

        GUPPricingRule rule = this.selectPriceAttributeGroup(this.sourceLevel);

        if (rule)
        {
            if (!masterRecord.validateWrite() && !rule.validateWrite())
            {
                error(strFmt("@GlobalUnifiedPricing:GUPPricingRuleBuilder_RecordNotValid", masterRecord.RecId));
            }
        }
        else
        {
            warning("@GlobalUnifiedPricing:GUPPricingRuleBuilder_FailToGeneratePricingRule");

            ttsbegin;

            rule.selectForUpdate(true);
            rule.delete();

            ttscommit;
        }
    }
}

private GUPPricingRule selectPriceAttributeGroup(GUPPricingAttributeSourceLevel _sourceLevel)
{
    xArgs args = new Args();

    Form createRuleForm = new Form(formStr(GUPAddPriceAttributeGroup));
    args.object(createRuleForm);
    args.parmEnumType(enumNum(GUPPricingAttributeSourceLevel));
    args.parmEnum(enum2int(_sourceLevel));
    args.record(this.pricingRule);

    if (this.callerForm)
    {
        args.caller(this.callerForm);
    }

    FormRun addPriceAttributeGrp = ClassFactory.formRunClass(args);

    addPriceAttributeGrp.init();
    addPriceAttributeGrp.run();
    addPriceAttributeGrp.wait();

    GUPPricingRule rule;

    if (formHasMethod(addPriceAttributeGrp, identifierStr(masterRecord)))
    {
        rule = addPriceAttributeGrp.masterRecord() as GUPPricingRule;
    }

    return rule;
}

/// <summary>
/// Construct a dialog that can be used in method createMasterRecord or linkPricingRule
/// </summary>
/// <returns>The dialog object.</returns>
public Object dialog()
{
    return super();
}

/// <summary>
/// Get control values from dialog that can be used in method createMasterRecord or linkPricingRule
/// </summary>
/// <returns>True if Ok clicked; otherwise false.</returns>
public boolean getFromDialog()
{
    return super();
}
